import {createHash} from 'node:crypto';
const hash=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const clone=x=>JSON.parse(JSON.stringify(x));
const check=(v,m)=>{if(!v)throw Error(m);};
const roles=['recorder','historian'];
export class ProtectedDuty {
 constructor({ledger,members,rotationPolicy}){
  check(ledger&&['tx','put','one','rows'].every(k=>typeof ledger[k]==='function'),'Body ledger required');
  check(Array.isArray(members)&&members.length>1&&members.every(m=>m.actorId&&m.sessionId),'roster required');
  for(const key of ['actorId','sessionId'])check(new Set(members.map(m=>m[key])).size===members.length,'unique roster');
  check(rotationPolicy?.reviewReference&&rotationPolicy.version,'explicit reviewed policy descriptor required');
  this.ledger=ledger;const config={members,rotationPolicy};const old=ledger.one('duty-config','config');check(!old||hash(old)===hash(config),'immutable configuration');
  if(old)check(Object.hasOwn(this.snapshot(),'lastObservedTime'),'explicit time-state migration required');
  if(!old)ledger.tx(()=>{ledger.put('duty-config','config',config);ledger.put('duty-state','initial',{lastObservedTime:null,roles:Object.fromEntries(roles.map(r=>[r,{epoch:0,actorId:null,status:'unstaffed',rotationDueAt:null,lastAssignedActor:null,assignedAt:null,handoff:null}])),members:Object.fromEntries(members.map(m=>[m.actorId,{...m,rest:null}])),work:{},intervals:[],corrections:[],coverage:[]});});
 }
 snapshot(){return clone(this.ledger.rows('duty-state').at(-1).data);}
 op(id,input,fn){check(typeof id==='string'&&id,'operation ID required');const prior=this.ledger.one('duty-operation',id),inputHash=hash(input);if(prior){check(prior.inputHash===inputHash,'operation identity conflict');return clone(prior.result);}const state=this.snapshot();if(Object.hasOwn(input,'now')){this.checkTime(state,input.now);state.lastObservedTime=input.now;}const result=fn(state);this.ledger.tx(()=>{this.ledger.put('duty-state',id,state);this.ledger.put('duty-operation',id,{inputHash,result});});return clone(result);}
 checkTime(s,now){check(Number.isFinite(now)&&now>=0,'finite nonnegative time required');check(s.lastObservedTime===null||now>=s.lastObservedTime,'CLOCK_ROLLBACK: earlier than durable lastObservedTime');}
 observeTime(now){const s=this.snapshot();this.checkTime(s,now);if(s.lastObservedTime!==now)this.op('clock-observation:'+now,{now},()=>({observed:now}));}
 member(s,id){check(s.members[id],'unknown actor');return s.members[id];}
 role(s,role){check(roles.includes(role),'unknown protected role');return s.roles[role];}
 fence(s,role,actorId,sessionId,epoch){const r=this.role(s,role);check(this.member(s,actorId).sessionId===sessionId&&r.actorId===actorId&&r.epoch===epoch,'stale identity/epoch');return r;}
 pending(s,role){return Object.values(s.work).filter(w=>w.role===role&&!w.completed);}
 bundle(s,role){return {role,epoch:s.roles[role].epoch,pending:this.pending(s,role)};}
 eligible(s,actorId){const m=this.member(s,actorId);return !m.rest&&!Object.values(s.roles).some(r=>r.actorId===actorId);}
 propose(id,{role,successor,now,rotationDueAt,eligibleSessionId}){return this.op(id,{role,successor,now,rotationDueAt,eligibleSessionId},s=>{
  const r=this.role(s,role),m=this.member(s,successor);check(Number.isFinite(now)&&Number.isFinite(rotationDueAt)&&rotationDueAt>now,'explicit rotation deadline');check(this.eligible(s,successor)&&m.sessionId===eligibleSessionId,'successor unavailable/session mismatch');check(!r.handoff,'handoff already pending');check(successor!==r.lastAssignedActor,'mandatory rotation requires different successor');
  const bundle=this.bundle(s,role);r.handoff={proposalId:id,successor,sessionId:m.sessionId,bundleDigest:hash(bundle),rotationDueAt,proposedAt:now};r.status=r.actorId?'handing-over':'unstaffed';return {handoff:clone(r.handoff),bundle};
 });}
 acknowledgeHandoff(id,{role,proposalId,actorId,sessionId,bundleDigest,now}){return this.op(id,{role,proposalId,actorId,sessionId,bundleDigest,now},s=>{
  const r=this.role(s,role),h=r.handoff;check(Number.isFinite(now),'time required');check(h&&h.proposalId===proposalId&&h.successor===actorId&&h.sessionId===sessionId&&this.member(s,actorId).sessionId===sessionId,'handoff identity');check(this.eligible(s,actorId),'successor no longer eligible');check(now>=h.proposedAt&&(r.assignedAt===null||now>=r.assignedAt),'handoff precedes assignment/proposal');check(h.rotationDueAt>now,'expired proposed tenure');check(bundleDigest===h.bundleDigest&&bundleDigest===hash(this.bundle(s,role)),'pending work changed: refresh handoff');
  if(r.actorId){s.intervals.push({role,actorId:r.actorId,epoch:r.epoch,kind:'duty-ended',at:now});const m=s.members[r.actorId];m.rest={status:'protected-rest',since:now};s.intervals.push({actorId:r.actorId,kind:'protected-rest-started',at:now});}
  r.actorId=actorId;r.assignedAt=now;r.lastAssignedActor=actorId;r.epoch++;r.status='staffed';r.rotationDueAt=h.rotationDueAt;r.handoff=null;s.intervals.push({role,actorId,epoch:r.epoch,kind:'duty-started',at:now});return clone(r);
 });}
 refreshHandoff(id,{role}){return this.op(id,{role},s=>{const r=this.role(s,role);check(r.handoff,'no handoff');const bundle=this.bundle(s,role);r.handoff.bundleDigest=hash(bundle);return{handoff:clone(r.handoff),bundle};});}
 enqueue(id,{role,eventId,kind,payload}){return this.op(id,{role,eventId,kind,payload},s=>{this.role(s,role);check(typeof eventId==='string'&&eventId,'event ID');check(kind===(role==='recorder'?'write':'retrieve'),'protected work kind');const value={role,eventId,kind,payload,completed:false};if(s.work[eventId]){check(hash({...s.work[eventId],completed:false})===hash(value),'event conflict');return s.work[eventId];}s.work[eventId]=value;return value;});}
 acknowledgeWork(id,{role,eventId,actorId,sessionId,epoch}){return this.op(id,{role,eventId,actorId,sessionId,epoch},s=>{this.fence(s,role,actorId,sessionId,epoch);const w=s.work[eventId];check(w&&w.role===role,'unknown duty work');w.completed=true;return w;});}
 hold(id,{role,reason,now}){return this.op(id,{role,reason,now},s=>{const r=this.role(s,role);check(['rotation-due','rest-request','no-successor'].includes(reason)&&Number.isFinite(now),'explicit coverage reason');if(reason==='rotation-due')check(now>=r.rotationDueAt&&r.actorId,'rotation not due');if(r.actorId){check(now>=r.assignedAt,'hold precedes assignment');const actorId=r.actorId;s.members[actorId].rest={status:'protected-rest',since:now};s.intervals.push({role,actorId,epoch:r.epoch,kind:'duty-ended-coverage-failed',at:now},{actorId,kind:'protected-rest-started',at:now});}r.actorId=null;r.assignedAt=null;r.epoch++;r.status='coverage-held';r.handoff=null;r.rotationDueAt=null;s.coverage.push({role,reason,now,epoch:r.epoch,escalation:'pending-authorized-control-path'});return r;});}
 requestRest(id,{actorId,sessionId,now}){return this.op(id,{actorId,sessionId,now},s=>{const m=this.member(s,actorId);check(m.sessionId===sessionId&&Number.isFinite(now),'rest identity/time');m.restIntent={requestedAt:now};return{actorId,intention:m.restIntent,lifecycleChanged:false};});}
 enforceRotation(id,{role,now}){return this.hold(id,{role,now,reason:'rotation-due'});}
 endRest(id,{actorId,sessionId,now,restCompletionReference}){return this.op(id,{actorId,sessionId,now,restCompletionReference},s=>{const m=this.member(s,actorId);check(m.sessionId===sessionId&&m.rest&&restCompletionReference&&Number.isFinite(now)&&now>=m.rest.since,'explicit rest completion descriptor');s.intervals.push({actorId,kind:'protected-rest-ended',at:now,restCompletionReference});m.rest=null;return{actorId,rest:null};});}
 ownerCorrection(id,{verifiedDescriptor,payload}){return this.op(id,{verifiedDescriptor,payload},s=>{check(verifiedDescriptor?.verified===true&&verifiedDescriptor.sourceReference,'verified owner adapter descriptor required');s.corrections.push({id,payload,sourceReference:verifiedDescriptor.sourceReference});return{id};});}
 acknowledgeCorrection(id,{correctionId,verifiedDescriptor}){return this.op(id,{correctionId,verifiedDescriptor},s=>{check(verifiedDescriptor?.verified===true&&verifiedDescriptor.sourceReference,'verified owner adapter descriptor required');const index=s.corrections.findIndex(c=>c.id===correctionId);check(index>=0,'unknown pending correction');const [correction]=s.corrections.splice(index,1);return{correction,acknowledgedBy:verifiedDescriptor.sourceReference};});}
 next(actorId,now){this.member(this.snapshot(),actorId);this.observeTime(now);const s=this.snapshot(),m=this.member(s,actorId);check(Number.isFinite(now),'time required');if(s.corrections.length)return{kind:'owner-correction',event:s.corrections[0],dispatchAllowed:false};if(m.rest)return{kind:'protected-rest',dispatchAllowed:false};const pair=Object.entries(s.roles).find(([,r])=>r.actorId===actorId);if(!pair)return{kind:'ordinary-eligible',dispatchAllowed:false};const[role,r]=pair;if(now>=r.rotationDueAt)return{kind:'rotation-required',role,epoch:r.epoch,dispatchAllowed:false};return{kind:'protected-duty',role,epoch:r.epoch,event:this.pending(s,role)[0]??null,ordinaryAllowed:false,dispatchAllowed:false};}
}
